<script setup lang="ts">
useSeoMeta({title:'Start a Project | Webonova',description:'Tell Webonova about your website, redesign, platform, or ongoing support needs.'}); const route=useRoute(); const form=reactive({name:'',email:'',phone:'',company:'',service:String(route.query.service||''),package:String(route.query.package||''),budget:'',launch:'',description:''}); const errors=ref<string[]>([]); function send(){errors.value=[]; if(!form.name.trim())errors.value.push('Please enter your name.'); if(!/^\S+@\S+\.\S+$/.test(form.email))errors.value.push('Please enter a valid email.'); if(!form.description.trim())errors.value.push('Please describe your project.'); if(errors.value.length)return; const subject=encodeURIComponent(`Website Project Inquiry${form.package?' — '+form.package:''}`); const body=encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\nPhone: ${form.phone}\nCompany: ${form.company}\nService: ${form.service}\nPackage: ${form.package}\nBudget: ${form.budget}\nLaunch: ${form.launch}\n\n${form.description}`); window.location.href=`mailto:webonovatech@gmail.com?subject=${subject}&body=${body}` }
</script>
<template><div><section class="page-hero section"><p class="eyebrow">START A PROJECT / MANILA</p><h1>Tell us what your<br>website needs to do.</h1><p class="lead">Share the essentials. We’ll recommend a practical next step and prepare a clear estimate.</p><p v-if="route.query.intent==='estimate'" class="red">Estimate request selected.</p></section><section class="contact section"><form novalidate @submit.prevent="send"><div v-if="errors.length" class="errors" role="alert"><p v-for="e in errors" :key="e">{{e}}</p></div><label>Name *<input v-model="form.name" autocomplete="name"></label><label>Email *<input v-model="form.email" type="email" autocomplete="email"></label><label>Phone <input v-model="form.phone" type="tel" autocomplete="tel"></label><label>Company <input v-model="form.company" autocomplete="organization"></label><label>Requested service<select v-model="form.service"><option value="">Select a service</option><option value="new-website">New website</option><option value="redesign">Website redesign</option><option value="platform">Booking or commerce platform</option><option value="support">Maintenance and support</option></select></label><label>Selected package<select v-model="form.package"><option value="">No package selected</option><option value="foundation">Foundation</option><option value="growth">Growth</option><option value="signature">Signature</option><option value="studio-hours">Studio Hours</option></select></label><label>Estimated budget<select v-model="form.budget"><option value="">Select a range</option><option>₱25K–₱60K</option><option>₱60K–₱120K</option><option>₱120K+</option></select></label><label>Desired launch period<input v-model="form.launch" placeholder="e.g. October 2026"></label><label class="wide">Project description *<textarea v-model="form.description" rows="7" placeholder="Your goals, audience, required features, and current challenges"></textarea></label><div class="wide"><button class="btn" type="submit">Prepare email inquiry →</button><p class="note">This opens a prefilled email to webonovatech@gmail.com so your inquiry is delivered through your own email provider.</p></div></form></section></div></template>
